import React, { useState, useEffect } from 'react';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, ResponsiveContainer } from 'recharts';
import '../styles/Dashboard.css';

function Dashboard({ status }) {
  const [metrics, setMetrics] = useState({
    avgLatency: 0,
    commandsProcessed: 0,
    uptime: 0,
  });
  const [latencyData, setLatencyData] = useState([]);

  useEffect(() => {
    loadMetrics();
    const interval = setInterval(loadMetrics, 5000); // Refresh every 5 seconds
    return () => clearInterval(interval);
  }, []);

  const loadMetrics = async () => {
    try {
      const result = await window.electronAPI.getMetrics();
      if (result.success) {
        setMetrics(result.metrics);
        // Add data point to chart
        setLatencyData((prev) => [
          ...prev.slice(-19), // Keep last 20 points
          {
            time: new Date().toLocaleTimeString(),
            latency: result.metrics.avgLatency || 0,
          },
        ]);
      }
    } catch (error) {
      console.error('Error loading metrics:', error);
    }
  };

  return (
    <div className="dashboard">
      {/* Status Cards */}
      <div className="cards-grid">
        <div className="card status-card">
          <h3>Status</h3>
          <div className={`status-value ${status}`}>
            {status === 'running' && '🟢 Online'}
            {status === 'stopped' && '🔴 Offline'}
            {status === 'error' && '⚠️ Error'}
            {status === 'unknown' && '❓ Unknown'}
          </div>
          <p className="card-description">JARVIS is {status}</p>
        </div>

        <div className="card metric-card">
          <h3>Avg Latency</h3>
          <div className="metric-value">{metrics.avgLatency?.toFixed(0) || 0}ms</div>
          <p className="card-description">Response time</p>
        </div>

        <div className="card metric-card">
          <h3>Commands</h3>
          <div className="metric-value">{metrics.commandsProcessed || 0}</div>
          <p className="card-description">Processed in session</p>
        </div>

        <div className="card metric-card">
          <h3>Uptime</h3>
          <div className="metric-value">
            {Math.floor((metrics.uptime || 0) / 60)}m
          </div>
          <p className="card-description">Time running</p>
        </div>
      </div>

      {/* Latency Chart */}
      <div className="card chart-card">
        <h3>Latency Over Time</h3>
        {latencyData.length > 0 ? (
          <ResponsiveContainer width="100%" height={300}>
            <LineChart data={latencyData}>
              <CartesianGrid strokeDasharray="3 3" stroke="#333" />
              <XAxis dataKey="time" stroke="#999" />
              <YAxis stroke="#999" label={{ value: 'Latency (ms)', angle: -90, position: 'insideLeft' }} />
              <Tooltip
                contentStyle={{
                  backgroundColor: '#1a1a1a',
                  border: '1px solid #00ff00',
                  borderRadius: '4px',
                }}
              />
              <Line type="monotone" dataKey="latency" stroke="#00ff00" dot={false} isAnimationActive={false} />
            </LineChart>
          </ResponsiveContainer>
        ) : (
          <p className="placeholder">No data yet. Start JARVIS to see metrics.</p>
        )}
      </div>

      {/* Quick Actions */}
      <div className="quick-actions">
        <h3>Quick Actions</h3>
        <div className="action-buttons">
          <button className="action-btn">
            🔊 Test Voice
          </button>
          <button className="action-btn">
            📁 Open Logs
          </button>
          <button className="action-btn">
            🔄 Restart
          </button>
          <button className="action-btn">
            🎤 Record Demo
          </button>
        </div>
      </div>

      {/* Features Status */}
      <div className="card features-card">
        <h3>Features</h3>
        <div className="features-list">
          <div className="feature">
            <span className="feature-icon">✅</span>
            <div>
              <strong>Web Search</strong>
              <p>Real-time DuckDuckGo integration</p>
            </div>
          </div>
          <div className="feature">
            <span className="feature-icon">✅</span>
            <div>
              <strong>Coding Assistant</strong>
              <p>Expert programming help (all languages)</p>
            </div>
          </div>
          <div className="feature">
            <span className="feature-icon">✅</span>
            <div>
              <strong>Fast Responses</strong>
              <p>Sub-2 second response times</p>
            </div>
          </div>
          <div className="feature">
            <span className="feature-icon">✅</span>
            <div>
              <strong>Voice Control</strong>
              <p>Hands-free command execution</p>
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}

export default Dashboard;
